async function useTools(db,step,row,member,relevantSeconds,timestamp,requested,assetChoices){
 const required=new Set(JSON.parse(step.required_items||'[]').map(String));let selected;if(requested===undefined)selected=[...required];else{if(!Array.isArray(requested))throw new InventoryError('De gekozen gereedschappen zijn ongeldig.');selected=[...new Set(requested.map(String))];if(selected.some(sku=>!required.has(sku)))throw new InventoryError('Een gekozen gereedschap hoort niet bij deze werkstap.');}
 const entries=[];for(const sku of selected){const item=await db.prepare("SELECT * FROM inventory_items WHERE sku=? AND tracking_mode IN ('tool','equipment')").bind(sku).first();if(!item)continue;const assets=(await db.prepare('SELECT * FROM tool_assets WHERE sku=? AND active=1 ORDER BY acquired_at,rowid').bind(sku).all()).results,chosen=assetChoices&&typeof assetChoices==='object'&&!Array.isArray(assetChoices)?assetChoices[sku]:null;if(assets.length>1&&!chosen)throw new InventoryError(`Kies het gebruikte exemplaar van ${item.name}.`,409);const asset=chosen?assets.find(a=>a.id===chosen):assets[0];if(!asset)throw new InventoryError(`${item.name} is nog niet als ontvangen gereedschap geregistreerd.`,409);const alreadyUsed=await db.prepare('SELECT id FROM maintenance_usage WHERE material_id=? AND tool_asset_id=? LIMIT 1').bind(row.material_id,asset.id).first();entries.push({sku,asset,alreadyUsed:Boolean(alreadyUsed),cost:Number(asset.acquisition_cost)/(Number(asset.allocation_target)||300)});}
 const statements=[];for(const entry of entries){if(entry.alreadyUsed)statements.push(db.prepare('UPDATE tool_assets SET total_seconds=total_seconds+?,last_used_at=? WHERE id=?').bind(relevantSeconds,timestamp,entry.asset.id));else statements.push(db.prepare('UPDATE tool_assets SET uses_count=uses_count+1,total_seconds=total_seconds+?,first_used_at=COALESCE(first_used_at,?),last_used_at=? WHERE id=?').bind(relevantSeconds,timestamp,timestamp,entry.asset.id),db.prepare('INSERT INTO maintenance_usage(id,step_id,material_id,sku,tool_asset_id,quantity,unit,cost_snapshot,is_training,member_id,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?)').bind(crypto.randomUUID(),step.id,row.material_id,entry.sku,entry.asset.id,1,'gebruik',entry.cost,Number(row.is_training)||0,member.id,timestamp));}if(statements.length)await db.batch(statements);
}

async function finishStep(db,id,member,raw){
 const row=await stepAndMaterial(db,id);assertStepAccess(row,member);const session=await db.prepare('SELECT * FROM maintenance_step_sessions WHERE step_id=? AND member_id=? AND ended_at IS NULL').bind(id,member.id).first();if(!session)throw new InventoryError('Start of hervat deze stap eerst.',409);let confirmation;try{confirmation=guideConfirmation(row.step_code,materialFromStep(row),raw.guideChecks,await resolvedGuide(db,row,materialFromStep(row)));}catch(error){throw new InventoryError(error.message);}
 if(yellowCleaningStep(row)&&Number(raw.cleanerMl||0)!==0)throw new InventoryError('Deze reinigingsstap registreert gele wax, geen chemische cleaner.');
 const timestamp=now(),seconds=Math.max(1,Math.round((new Date(timestamp).getTime()-new Date(session.started_at).getTime())/1000)),consumptions=[];
 if(yellowCleaningStep(row)||['base_wax','wax','practice_wax'].includes(row.step_code)){const start=await db.prepare("SELECT * FROM maintenance_measurements WHERE step_id=? AND measurement_type='weight_start' ORDER BY created_at LIMIT 1").bind(id).first(),endWeight=Number(raw.endWeight);if(!start)throw new InventoryError('Het startgewicht van de wax ontbreekt.',409);if(!Number.isFinite(endWeight)||endWeight<0||endWeight>Number(start.value))throw new InventoryError('Het eindgewicht moet gelijk aan of lager zijn dan het startgewicht.');const used=Number(start.value)-endWeight;await stockItem(db,start.sku,used);consumptions.push({sku:start.sku,quantity:used});}
 const cleanerMl=Number(raw.cleanerMl||0),fleeceCm=Number(raw.fleeceCm||0),repairStrips=Number(raw.repairStrips||0),options=row.selected_options?JSON.parse(row.selected_options):{},waxsticks=row.step_code==='waxstick'?Number(options.waxstickCount)||0:0;if(!Number.isFinite(cleanerMl)||cleanerMl<0||cleanerMl>500)throw new InventoryError('Controleer het aantal milliliter cleaner.');if(!Number.isFinite(fleeceCm)||fleeceCm<0||fleeceCm>2000)throw new InventoryError('Controleer de lengte fleece.');if(!Number.isInteger(repairStrips)||repairStrips<0||repairStrips>50)throw new InventoryError('Controleer het aantal repair-strips.');if(cleanerMl)await stockItem(db,'25422',cleanerMl);if(fleeceCm)await stockItem(db,'24491',fleeceCm);if(repairStrips)await stockItem(db,raw.repairColor==='black'?'24409':'24408',repairStrips);if(waxsticks)await stockItem(db,'25018',waxsticks);
 await useTools(db,row,row,member,Number(row.duration_seconds||0)+seconds,timestamp,raw.toolSkus,raw.toolAssets);
 await db.batch([db.prepare('UPDATE maintenance_step_sessions SET ended_at=?,duration_seconds=? WHERE id=?').bind(timestamp,seconds,session.id),db.prepare("UPDATE maintenance_steps SET status='completed',completed_at=?,duration_seconds=duration_seconds+? WHERE id=?").bind(timestamp,seconds,id),...(confirmation?[db.prepare('INSERT INTO material_events(material_id,actor,event_type,detail,created_at) VALUES(?,?,?,?,?)').bind(row.material_id,member.id,'step_checks',JSON.stringify({stepId:id,...confirmation}),timestamp)]:[])]);
 if(yellowCleaningStep(row)||['base_wax','wax','practice_wax'].includes(row.step_code)){const start=await db.prepare("SELECT * FROM maintenance_measurements WHERE step_id=? AND measurement_type='weight_start' ORDER BY created_at LIMIT 1").bind(id).first();await db.prepare('INSERT INTO maintenance_measurements(id,step_id,material_id,sku,measurement_type,value,unit,note,member_id,created_at) VALUES(?,?,?,?,?,?,?,?,?,?)').bind(crypto.randomUUID(),id,row.material_id,start.sku,'weight_end',Number(raw.endWeight),'g',clean(raw.note,200),member.id,timestamp).run();}
 for(const usage of consumptions)await consumeItem(db,{...usage,step:row,row,member,timestamp});if(cleanerMl)await consumeItem(db,{sku:'25422',quantity:cleanerMl,step:row,row,member,timestamp});if(fleeceCm)await consumeItem(db,{sku:'24491',quantity:fleeceCm,step:row,row,member,timestamp});if(repairStrips)await consumeItem(db,{sku:raw.repairColor==='black'?'24409':'24408',quantity:repairStrips,step:row,row,member,timestamp});if(waxsticks)await consumeItem(db,{sku:'25018',quantity:waxsticks,step:row,row,member,timestamp});
 const remaining=await db.prepare("SELECT COUNT(*) amount FROM maintenance_steps WHERE material_id=? AND status NOT IN ('completed','skipped')").bind(row.material_id).first();
 if(Number(remaining?.amount)===0){
  if(Number(row.is_training))await db.prepare("UPDATE materials SET internal_status='ready',customer_status='Oefensessie afgerond',ready_at=?,updated_at=? WHERE id=?").bind(timestamp,timestamp,row.material_id).run();
  else{await db.prepare("UPDATE materials SET internal_status='ready',customer_status='Klaar om opgehaald te worden',ready_at=?,updated_at=? WHERE id=?").bind(timestamp,timestamp,row.material_id).run();const openSiblings=await db.prepare("SELECT COUNT(*) amount FROM materials WHERE reference=? AND is_training=0 AND internal_status NOT IN ('ready','delivered')").bind(row.reference).first();if(Number(openSiblings?.amount)===0)await db.prepare(`UPDATE records SET payload=json_set(payload,'$.customerStatus','Klaar om opgehaald te worden','$.status','Klaar om opgehaald te worden','$.currentStep',8,'$.updatedAt',?),actor='workflow',updated_at=? WHERE reference=?`).bind(timestamp,timestamp,row.reference).run();}
 }else await db.prepare("UPDATE materials SET internal_status='paused',updated_at=? WHERE id=?").bind(timestamp,row.material_id).run();return getWorkflow(db,await db.prepare('SELECT * FROM materials WHERE id=?').bind(row.material_id).first());
}

export async function handleInventory(request,env,{owner,json,origin}){
 const path=new URL(request.url).pathname,db=env.LATTENSPECIALIST_TEAM_DB;try{
  if(!db)throw new InventoryError('Bedrijfsdatabase niet beschikbaar.',503);
  if(path.startsWith('/api/admin/inventory')){
   if(!owner)throw new InventoryError('Geen toegang tot beheer.',401);await ensureToolStock(db);if(path==='/api/admin/inventory/overview'&&request.method==='GET')return json(await inventoryOverview(db),200,origin);
   if(path==='/api/admin/inventory/suppliers'&&request.method==='POST'){const supplierId=await createSupplier(db,await readBody(request));return json({supplierId,...await inventoryOverview(db)},201,origin);}
   const supplier=path.match(/^\/api\/admin\/inventory\/suppliers\/([a-z0-9-]{1,60})$/);if(supplier&&request.method==='PATCH'){const supplierId=await updateSupplier(db,supplier[1],await readBody(request));return json({supplierId,...await inventoryOverview(db)},200,origin);}
   const adjust=path.match(/^\/api\/admin\/inventory\/items\/([a-zA-Z0-9_-]{1,40})\/adjust$/);if(adjust&&request.method==='POST'){const adjustment=await adjustInventoryItem(db,adjust[1],await readBody(request),'owner');return json({adjustment,...await inventoryOverview(db)},200,origin);}
   const item=path.match(/^\/api\/admin\/inventory\/items\/([a-zA-Z0-9_-]{1,40})$/);if(item&&request.method==='PATCH'){const updatedItem=await updateInventoryItem(db,item[1],await readBody(request));return json({updatedItem,...await inventoryOverview(db)},200,origin);}
   const activate=path.match(/^\/api\/admin\/inventory\/items\/([a-zA-Z0-9_-]{1,40})\/activate$/);if(activate&&request.method==='POST'){const activated=await activateTools(db,activate[1],await readBody(request),'owner',InventoryError);return json({activated,...await inventoryOverview(db)},201,origin);}
   if(path==='/api/admin/inventory/guides'&&request.method==='GET')return json(await guideCatalog(db),200,origin);const guidePath=path.match(/^\/api\/admin\/inventory\/guides\/([a-zA-Z0-9_]+)$/);if(guidePath&&request.method==='PATCH')return json(await saveGuide(db,guidePath[1],await readBody(request),InventoryError),200,origin);
   const receive=path.match(/^\/api\/admin\/inventory\/orders\/([a-z0-9-]+)\/receive$/);if(receive&&request.method==='POST'){await receiveOrder(db,receive[1],'owner');return json(await inventoryOverview(db),200,origin);}
   const replace=path.match(/^\/api\/admin\/inventory\/tools\/([a-f0-9-]{36})\/replace$/);if(replace&&request.method==='POST'){const replacementId=await replaceTool(db,replace[1],await readBody(request),'owner');return json({replacementId,...await inventoryOverview(db)},201,origin);}throw new InventoryError('Niet gevonden.',404);
  }
  const ownerWorkflow=path.match(/^\/api\/admin\/operations\/materials\/([a-f0-9-]{36})\/workflow$/);
  if(ownerWorkflow&&request.method==='GET'){if(!owner)throw new InventoryError('Geen toegang tot beheer.',401);await ensureToolStock(db);const material=await db.prepare('SELECT * FROM materials WHERE id=?').bind(ownerWorkflow[1]).first();if(!material)throw new InventoryError('Materiaal niet gevonden.',404);return json({material:materialView(material),workflow:await getWorkflow(db,material)},200,origin);}
  const member=await memberIdentity(request,db);if(path==='/api/team/guides'&&request.method==='GET')return json(await guideCatalog(db),200,origin);
  if(path==='/api/team/practice'&&request.method==='POST')return json(await createPractice(db,member,await readBody(request)),201,origin);
  const workflow=path.match(/^\/api\/team\/operations\/materials\/([a-f0-9-]{36})\/workflow$/);if(workflow&&request.method==='GET'){const material=await db.prepare('SELECT * FROM materials WHERE id=?').bind(workflow[1]).first();if(!material)throw new InventoryError('Materiaal niet gevonden.',404);if(material.assigned_to&&material.assigned_to!==member.id)throw new InventoryError('Deze opdracht is aan een andere medewerker toegewezen.',403);return json({material:materialView(material),workflow:await getWorkflow(db,material)},200,origin);}
  const action=path.match(/^\/api\/team\/operations\/steps\/([a-f0-9-]{36})\/(start|pause|finish)$/);if(action&&request.method==='POST'){const raw=await readBody(request),result=action[2]==='start'?await startStep(db,action[1],member,raw):action[2]==='pause'?await pauseStep(db,action[1],member):await finishStep(db,action[1],member,raw);const row=await stepAndMaterial(db,action[1]),material=materialView(materialFromStep(row));return json({material,workflow:result},200,origin);}throw new InventoryError('Niet gevonden.',404);
 }catch(error){return json({message:error instanceof InventoryError?error.message:'Voorraad en werkstappen zijn tijdelijk niet beschikbaar.'},error instanceof InventoryError?error.status:503,origin);}
}
